using System;
using System.Collections.Generic;

namespace Hollowmere.EditorTools
{
    // Plain C# twins of the design pack JSON (docs/design/, generated by tools/housegen/). DesignData loads them with
    // a snake_case naming strategy (PuzzleKindM1 <- "puzzle_kind_m1") and fails on any JSON key that has no field here,
    // so a schema change in housegen shows up as a load error instead of silently dropped data.
    // Coordinates: metres. Houses are house-local (origin = main wing centre at ground-floor level, +z = front);
    // rects are (x0, z0, x1, z1). The village is Unity world space. Yaw is Unity Y rotation in degrees.

    // ------------------------------------------------------------------ houses/Hxx.json (schema hollowmere.house/1)

    public sealed class HouseSpec
    {
        public string Schema;
        public string Slug;
        public int Index;
        public string Name;
        public string Family;
        public string Part;
        public string PuzzleKindM1;
        public string DoorColour;
        public int Chimneys;
        public int ClockHour;
        public bool LoudPuzzle;
        public string Archetype;
        public string Silhouette;
        public HouseWorldSpec World;
        public string Conventions;
        public Dictionary<string, LevelSpec> Levels = new Dictionary<string, LevelSpec>();
        public WingSpec[] Wings = Array.Empty<WingSpec>();
        public RoomSpec[] Rooms = Array.Empty<RoomSpec>();
        public DoorSpec[] Doors = Array.Empty<DoorSpec>();
        public WindowSpec[] Windows = Array.Empty<WindowSpec>();
        public StairSpec[] Stairs = Array.Empty<StairSpec>();
        public ChimneySpec[] ChimneysDetail = Array.Empty<ChimneySpec>();
        public PropSpec[] Props = Array.Empty<PropSpec>();
        public AnchorSpec[] Anchors = Array.Empty<AnchorSpec>();
        public string[] Exterior = Array.Empty<string>();
        public string[] Plot = Array.Empty<string>();
        public string[] Puzzle = Array.Empty<string>();
        public string[] NightChanges = Array.Empty<string>();
        public string[] Audio = Array.Empty<string>();
        public string[] References = Array.Empty<string>();
        public string ImagePrompt;

        public RoomSpec FindRoom(string id)
        {
            foreach (var r in Rooms) if (r.Id == id) return r;
            return null;
        }

        public PropSpec FindProp(string id)
        {
            foreach (var p in Props) if (p.Id == id) return p;
            return null;
        }
    }

    public sealed class HouseWorldSpec
    {
        public float[] Position = Array.Empty<float>();   // x, y = ground-floor level, z
        public float Yaw;                                  // the way the front faces
        public string Street;
        public float[][] PlotPoly = Array.Empty<float[]>(); // world (x, z) corners
        public string Note;
    }

    public sealed class LevelSpec
    {
        public float Y;       // floor height above the house origin
        public float H;       // floor-to-ceiling height
        public string Label;
    }

    public sealed class WingSpec
    {
        public string Id;
        public float[] Rect = Array.Empty<float>();
        public string[] Levels = Array.Empty<string>();
        public string Walls;  // material keys + description
        public float T;       // exterior wall thickness, taken inside the rect
        public string Roof;
        public string Note;
    }

    public sealed class RoomSpec
    {
        public string Id;
        public string Name;
        public string Level;
        public float[] Rect = Array.Empty<float>();   // to the outer face of exterior walls / centre of partitions
        public float[] Inner = Array.Empty<float>();  // the free floor inside the walls
        public string Kind;
        public string Floor;  // material key
        public string Walls;
        public string Ceiling;
        public string Light;
        public string Skirting;
        public string Note;
    }

    public abstract class OpeningSpec
    {
        public string Id;
        public string Side;   // N, S, E or W wall of the room
        public float At;      // centre along the wall: x for N/S walls, z for E/W walls
        public float Width;
        public float Height;
        public string Note;
    }

    public sealed class DoorSpec : OpeningSpec
    {
        public string Level;
        public string RoomA;
        public string RoomB;  // a room id, or "ext"
        public string Kind;
        public string Mat;    // material key
        public string Colour; // door colour name, or null
        public string Role;   // "front", "back" or ""
        public string Swing;
    }

    public sealed class WindowSpec : OpeningSpec
    {
        public string Room;
        public float Sill;
        public string Style;
        public bool Weak;
        public string Curtains;
        public string Shutters;
    }

    public sealed class StairSpec
    {
        public string Id;
        public string Room;
        public float[] Rect = Array.Empty<float>();
        public string Frm;    // level the stair starts on
        public string To;
        public string Ascent; // direction of travel going up: N, S, E or W
        public string Kind;
        public string Mat;
        public string Note;
    }

    public sealed class ChimneySpec
    {
        public float X;
        public float Z;
        public float W;
        public float D;
        public float AboveRidge;
        public string Mat;
        public string Serves;
        public int Pots;
    }

    public sealed class PropSpec
    {
        public string Id;
        public int N;         // the number on the plan PNG
        public string Room;
        public string Key;    // asset catalog key
        public float X;
        public float Y;
        public float Z;
        public float Yaw;
        public string Role;
        public string Note;
        public string On;     // id of the prop this one stands on, or null
        public string Mat;
        public float? Scale;
        public string Asset;
        public string Source;
        public float[] Dims = Array.Empty<float>(); // w, d, h before Scale
        public bool Hung;
    }

    public sealed class AnchorSpec
    {
        public string Kind;   // hiding, item-spot, note-spot, puzzle, container, shrine...
        public string Room;
        public float X;
        public float Y;
        public float Z;
        public float Yaw;
        public string Note;
    }

    // ------------------------------------------------------------------ village.json (schema hollowmere.village/1)

    public sealed class VillageSpec
    {
        public string Schema;
        public string Conventions;
        public VillageBoundsSpec Bounds;
        public TerrainSpec Terrain;
        public VillageHouseSpec[] Houses = Array.Empty<VillageHouseSpec>();
        public LandmarkSpec[] Landmarks = Array.Empty<LandmarkSpec>();
        public FillerSpec[] Filler = Array.Empty<FillerSpec>();
        public RoadSpec[] Roads = Array.Empty<RoadSpec>();
        public StreamSpec Stream;
        public BridgeSpec[] Bridges = Array.Empty<BridgeSpec>();
        public BlockerSpec[] NightBlockers = Array.Empty<BlockerSpec>();
        public float[][] Scarecrows = Array.Empty<float[]>();  // world (x, z)
        public float[][] StreetLamps = Array.Empty<float[]>(); // world (x, z)

        public VillageHouseSpec FindHouse(string slug)
        {
            foreach (var h in Houses) if (h.Slug == slug) return h;
            return null;
        }

        public LandmarkSpec FindLandmark(string id)
        {
            foreach (var l in Landmarks) if (l.Id == id) return l;
            return null;
        }
    }

    public sealed class VillageBoundsSpec
    {
        public float[] InsideWall = Array.Empty<float>();      // x0, z0, x1, z1
        public float[] ForestBeltInner = Array.Empty<float>(); // x0, z0, x1, z1
        public float WallHeight;
    }

    public sealed class TerrainSpec
    {
        public string Note;
        public HeightPointSpec[] HeightPoints = Array.Empty<HeightPointSpec>();
    }

    public sealed class HeightPointSpec
    {
        public string Name;
        public float X;
        public float Z;
        public float Y;
    }

    public sealed class VillageHouseSpec
    {
        public string Slug;
        public string Name;
        public float[] Position = Array.Empty<float>(); // x, y = ground-floor level, z
        public float Yaw;
        public string Street;
        public float[] FrontDoor = Array.Empty<float>(); // world (x, z) of the front door's outer face
        public float[][] PlotPoly = Array.Empty<float[]>();
        public float ToAltar;                            // metres, front door to the altar centre
    }

    public sealed class LandmarkSpec
    {
        public string Id;
        public string Name;
        public float[] Pos = Array.Empty<float>();  // world (x, z) centre
        public float[] Size = Array.Empty<float>(); // w, d before yaw
        public float Yaw;
        public string Kind;
        public bool Keep;     // true = already built by GreyboxVillageBuilder, stays where it is
        public string Note;
    }

    public sealed class FillerSpec
    {
        public string Id;
        public string Name;
        public float[] Pos = Array.Empty<float>();
        public float[] Size = Array.Empty<float>();
        public float Yaw;
    }

    public sealed class RoadSpec
    {
        public string Id;
        public string Name;
        public string Kind;
        public float Width;
        public float[][] Points = Array.Empty<float[]>(); // world (x, z) centreline
        public float Length;
    }

    public sealed class StreamSpec
    {
        public float[][] Points = Array.Empty<float[]>();
        public float Width;
        public float BedY;
    }

    public sealed class BridgeSpec
    {
        public string Id;
        public string Name;
        public float[] Pos = Array.Empty<float>();
        public float Width;
        public float Length;
    }

    public sealed class BlockerSpec
    {
        public string Id;
        public string Prop;   // asset catalog key
        public float[] Pos = Array.Empty<float>();
    }

    // ------------------------------------------------------------------ asset_catalog.json

    public sealed class AssetCatalogSpec
    {
        public MaterialEntrySpec[] Materials = Array.Empty<MaterialEntrySpec>();
        public ModelEntrySpec[] Models = Array.Empty<ModelEntrySpec>();
        public AudioEntrySpec[] Audio = Array.Empty<AudioEntrySpec>();
        public string SonnissRoot;

        public ModelEntrySpec FindModel(string key)
        {
            foreach (var m in Models) if (m.Key == key) return m;
            return null;
        }

        public MaterialEntrySpec FindMaterial(string key)
        {
            foreach (var m in Materials) if (m.Key == key) return m;
            return null;
        }

        /// <summary>True for any model or material key.</summary>
        public bool HasKey(string key) => key != null && (FindModel(key) != null || FindMaterial(key) != null);
    }

    public sealed class MaterialEntrySpec
    {
        public string Key;
        public string Kind;
        public string Source;
        public string Id;
        public string Res;
        public string Use;
        public string Download;
        public string Licence;
        public string Note;
    }

    public sealed class ModelEntrySpec
    {
        public string Key;
        public string Kind;
        public string Source;   // polyhaven, sketchfab, owned, procedural
        public string Id;
        public string Res;
        public float[] Dims = Array.Empty<float>(); // w, d, h in metres
        public string Download;
        public string Licence;
        public string Author;
        public string Note;
        public string Upgrade;
        public string[] Tags = Array.Empty<string>();
    }

    public sealed class AudioEntrySpec
    {
        public string Key;
        public string Folder;
        public string Use;
    }
}
